mapper.select:
SELECT p.*, u.real_name as leader_name, c.college_name
FROM research_project p
LEFT JOIN sys_user u ON p.leader_id = u.id
LEFT JOIN sys_college c ON p.college_id = c.id
WHERE p.deleted = 0

    AND (p.project_name LIKE CONCAT('%',#{keyword},'%') OR p.project_source LIKE CONCAT('%',#{keyword},'%'))


    AND p.project_category = #{category}


    AND p.project_type = #{type}


    AND p.status = #{status}


    AND p.leader_id = #{leaderId}


    AND p.college_id = #{collegeId}

ORDER BY p.create_time DESC
